$('enter').onclick=()=>{if(!route||animating)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){setMode('terrain');return}animating=true;controls.enabled=false;const from=camera.position.clone(),target=earthPoint(114.19,27.49,6.1),start=performance.now();function fly(t){const p=Math.min(1,(t-start)/1050),ease=p*p*(3-2*p);camera.position.lerpVectors(from,target,ease);camera.lookAt(0,0,0);if(p<1)requestAnimationFrame(fly);else{animating=false;controls.enabled=true;setMode('terrain')}}requestAnimationFrame(fly)};
