$('play').onclick=()=>{if(progress>=1)setProgress(0);playing=!playing;updatePlay()};$('progress').oninput=e=>{playing=false;setProgress(Number(e.target.value)/1000);updatePlay()};$('speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;$('speed').textContent=speed+'×'};
