try{const responses=await Promise.all([fetch('./route.json'),fetch('./terrain.json')]);if(responses.some(r=>!r.ok))throw Error('数据读取失败');[route,terrain]=await Promise.all(responses.map(r=>r.json()));dist=route.distances;makeTerrain();const km=(route.length/1000).toFixed(1);$('distance').innerHTML=km+'<em> km</em>';$('maxAlt').innerHTML=route.maxAltitude+'<em> m</em>';$('cardDistance').textContent=km+' km';$('totalKm').textContent=km;let path='';const min=route.minAltitude,max=route.maxAltitude;for(let i=0;i<route.points.length;i++){let x=dist[i]/dist.at(-1)*700,y=59-(route.points[i][2]-min)/(max-min)*52;path+=(i?'L':'M')+x.toFixed(1)+','+y.toFixed(1)}$('profilePath').setAttribute('d',path);$('areaPath').setAttribute('d',path+'L700,65L0,65Z');setProgress(0);$('loading').hidden=true;document.body.dataset.ready='true';window.__atlas={routePoints:points.length,terrainVertices:terrain.n**2,routeKm:route.length/1000,get mode(){return mode},get progress(){return progress}}}catch(e){console.error(e);$('loading').textContent='山野数据加载失败，请刷新页面重试。'}
